        \draw[thick] (A) -- (N);
    % Vẽ hình vuông nhỏ
    \fill[cyan!30] (F) -- (G) -- (H) -- (I) -- cycle; % Tô màu cho hình vuông
    \draw[thick] (F) -- (G) -- (H) -- (I) -- cycle;   % Vẽ các cạnh của hình vuông

    % Vẽ chiều cao của hình bình hành từ cạnh dưới lên cạnh trên

