Một mảnh vườn hình bình hành, giữa vườn người ta đào một cái ao hình vuông cạnh ${6}m$ như hình vẽ minh hoạ. Biết chiều cao h dài gấp $2$ cạnh hình vuông. Tính diện tích còn lại của vườn sau khi đào ao?
}{
\begin{tikzpicture}
    % Tọa độ các điểm của hình bình hành
    \coordinate (A) at (0,0);     % Góc dưới bên trái
    \coordinate (B) at (10,0);    % Góc dưới bên phải
    \coordinate (C) at (8,4);     % Góc trên bên phải
    \coordinate (D) at (-2,4);    % Góc trên bên trái

    \coordinate (N) at (0,4);    % Góc trên bên trái
    % Tọa độ các điểm của hình vuông nhỏ bên trong (cạnh = 3)
    \coordinate (E) at (3,2);     % Điểm trung tâm của hình vuông
    \coordinate (F) at (3,3.5);   % Điểm trên
    \coordinate (G) at (1.5,2);   % Điểm trái
    \coordinate (H) at (3,0.5);   % Điểm dưới
    \coordinate (I) at (4.5,2);   % Điểm phải

    % Vẽ hình bình hành
    \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;
        \draw[thick] (A) -- (N);
    % Vẽ hình vuông nhỏ
    \fill[cyan!30] (F) -- (G) -- (H) -- (I) -- cycle; % Tô màu cho hình vuông
    \draw[thick] (F) -- (G) -- (H) -- (I) -- cycle;   % Vẽ các cạnh của hình vuông

    % Vẽ chiều cao của hình bình hành từ cạnh dưới lên cạnh trên

    \node[right] at ($(A)!0.5!(N)$) {$h$}; % Chú thích chiều cao

    % Chú thích kích thước các cạnh
    \node[above] at ($(D)!0.5!(C)$) {$27$};   % Chú thích cạnh trên của hình bình hành
    \node[left] at ($(G)!0.5!(F)$) {$6$};     % Chú thích cạnh hình vuông nhỏ


    % Vẽ góc vuông tại chân đường cao
